const {fields,secrets}=require('./stream-redactor.cjs');
const spool=require('./text-spool.cjs');
const {createHash}=require('node:crypto');
const rpcText=require('./rpc-text.cjs');
// Only IDs generated by our Chat -> Responses adapter are coalesced. Native
// Responses items remain independent, including their paragraph boundaries.
function segment(message){
 const {method,params={}}=message,id=params.itemId||params.item?.id;
 const match=/^((msg|rs)_resp_[0-9a-f-]{36})_part_(\d+)$/.exec(id||'');
 if(!match||!['item/started','item/completed','item/agentMessage/delta','item/reasoning/textDelta','item/reasoning/summaryTextDelta','item/reasoning/summaryPartAdded'].includes(method))return;
 return {id,group:match[1],reasoning:match[2]==='rs'};
}
function apply(context,message,owner,key){
 const info=segment(message),{method,params={}}=message;
 context.bridgeSegments??=new Map();
 const identity=(params.threadId||'')+':'+info.group;
 let state=context.bridgeSegments.get(identity);
 if(!state){state={segments:new Map(),body:{text:''}};context.bridgeSegments.set(identity,state);}
 // Persistence may compact a completed visible segment to a lazy DB reference
 // while its response is still streaming. Keep the active append target owned
 // by the response and reattach its descriptor without reading that reference.
 const visible=owner,visibleKey=key;owner=state.body;key='text';
 let entry=state.segments.get(info.id);
 const length=()=>spool.reference(owner,key)?.length??String(owner[key]||'').length;
 if(!entry){entry={start:length(),length:0,order:state.segments.size,completed:false};state.segments.set(info.id,entry);}
 if(method==='item/completed'){
  if(!entry.completed)fields(context).reset(owner,key);
  const item=params.item;
  // A segment boundary must not publish an unfinished secret prefix. This is
  // also applied to authoritative completion, which can replace streamed text.
  const valueParts=()=>rpcText.redacted(context,rpcText.completedParts(item,info.reasoning),true),previous=spool.reference(owner,key);
  let valueLength=0;const valueHash=createHash('sha256');for(const part of valueParts()){valueLength+=part.length;valueHash.update(part,'utf16le');}
  const range=(start,end)=>previous?spool.chunks(previous,start,end):[String(owner[key]||'').slice(start,end)];
  const hash=createHash('sha256');for(const part of range(entry.start,entry.start+entry.length))hash.update(part,'utf16le');
  const same=entry.length===valueLength&&hash.digest('hex')===valueHash.digest('hex');
  if(!same){
   // Normal completions are identical and retain the append-only generation.
   // An authoritative correction rebuilds only this group's body, in bounded
   // chunks; historical segments are represented by offsets, never full text.
   if(context.textSpool&&(previous||length()-entry.length+valueLength>8192)){
    const replacement=context.textSpool.create();
    for(const part of range(0,entry.start))context.textSpool.append(replacement,part);
    for(const part of valueParts())context.textSpool.append(replacement,part);
    for(const part of range(entry.start+entry.length,length()))context.textSpool.append(replacement,part);
    spool.install(owner,key,replacement);
   }else {const old=String(owner[key]||'');owner[key]=old.slice(0,entry.start)+[...valueParts()].join('')+old.slice(entry.start+entry.length);}
   const difference=valueLength-entry.length;
   for(const other of state.segments.values())if(other.order>entry.order)other.start+=difference;
   entry.length=valueLength;
  }
  entry.completed=true;
 }else if(!entry.completed&&rpcText.isText(params,'delta')){
  for(const part of rpcText.parts(params,'delta'))fields(context).append(owner,key,part,secrets(context),{scope:params.threadId});entry.length=length()-entry.start;
 }
 const descriptor=Object.getOwnPropertyDescriptor(owner,key);
 if('value'in descriptor)fields(context).join(visible,visibleKey,()=>owner[key],params.threadId);
 else Object.defineProperty(visible,visibleKey,descriptor);
 return info;
}
module.exports={segment,apply};
